    public async Task<CreateApiKeyResultDto> CreateAsync(
        CreateApiKeyRequestDto request,
        string? createdByUserId,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.Name);

        var groupName = string.IsNullOrWhiteSpace(request.PermissionGroupName)
            ? "Admin"
            : request.PermissionGroupName.Trim();

        if (request.ExpiresAt <= DateTime.UtcNow)
            throw new InvalidOperationException("ExpiresAt must be in the future.");

        if (!await PermissionGroupExistsAsync(groupName, cancellationToken).ConfigureAwait(false))
            throw new InvalidOperationException($"Permission group '{groupName}' was not found.");

        var name = request.Name.Trim();
        if (await NameExistsAsync(name, cancellationToken).ConfigureAwait(false))
            throw new InvalidOperationException($"An API key named '{name}' already exists.");

        var (plaintext, prefix, hash) = ApiKeyHasher.Create(groupName);
        var id = Guid.NewGuid();
        var expiresAt = request.ExpiresAt.ToUniversalTime();
        var createdDate = DateTime.UtcNow;

        var inserted = await apiKeys.InsertAsync(new ApiKeyDto
        {
            Id = id,
            Name = name,
            Description = string.IsNullOrWhiteSpace(request.Description) ? null : request.Description.Trim(),
            KeyPrefix = prefix,
            KeyHash = hash,
            PermissionGroupName = groupName,
            CreatedByUserId = createdByUserId,
            Status = ApiKeyStatus.Active,
            IsActive = true,
            ExpiresAt = expiresAt,
            LastUsedAt = null,
            CreatedDate = createdDate,
            RevokedDate = null
        }).ConfigureAwait(false);

        if (inserted.Code != 0)
            throw new InvalidOperationException(inserted.Message);

        return new CreateApiKeyResultDto
        {
            Id = id,
            Name = name,
            KeyPrefix = prefix,
            ApiKey = plaintext,
            PermissionGroupName = groupName,
            ExpiresAt = expiresAt
        };
    }

    public async Task<bool> NameExistsAsync(string name, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(name))
            return false;

        var result = await apiKeys.ApiKeyNameIsExistsAsync(name.Trim()).ConfigureAwait(false);
        return result.Value;
