    public async Task<IReadOnlyList<ApiKeyListItemDto>> ListAsync(CancellationToken cancellationToken = default)
    {
        var countResult = await apiKeys.CountAsync().ConfigureAwait(false);
        if (countResult.Code != 0)
            throw new InvalidOperationException(countResult.Message ?? "Failed to count API keys.");

        var total = Math.Max(0, countResult.Value);
        if (total == 0)
            return [];

        var items = new List<ApiKeyListItemDto>(total);
        var pageSize = ConfigurationConstants.MaxPageSize;
        var pages = Math.Max(1, (int)Math.Ceiling(total / (double)pageSize));
        for (var page = 1; page <= pages; page++)
        {
            var pageResult = await apiKeys.ListAsync(page, pageSize).ConfigureAwait(false);
            if (pageResult.Code != 0)
                throw new InvalidOperationException(pageResult.Message ?? "Failed to list API keys.");
            if (pageResult.Value is null)
                continue;
            items.AddRange(pageResult.Value.Select(ToListItem));
        }

        return items;
    }

    public async Task<bool> RevokeAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var result = await apiKeys.RevokeApiKeyAsync(id, new RevokeApiKeyRequestDto()).ConfigureAwait(false);
        return result.Code == 0 && result.Value > 0;
