    public async Task<ValidateApiKeyResultDto> ValidateAsync(
        ValidateApiKeyRequestDto request,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        if (string.IsNullOrWhiteSpace(request.ApiKey) ||
            !request.ApiKey.Trim().StartsWith(ApiKeyHasher.KeyPrefixMarker, StringComparison.Ordinal))
        {
            return Invalid("Invalid API key format.");
        }

        var plaintext = request.ApiKey.Trim();
        var prefix = ApiKeyHasher.ExtractPrefix(plaintext);
        var presentedHash = ApiKeyHasher.HashPlaintext(plaintext);

        var byPrefix = await apiKeys.GetApiKeyByPrefixAsync(prefix).ConfigureAwait(false);
        var match = byPrefix.Value;
        if (match is null || !ApiKeyHasher.FixedTimeEquals(match.KeyHash, presentedHash))
            return Invalid("API key not found.");

        if (!match.IsActive || match.Status != ApiKeyStatus.Active)
        {
            await WriteUsageLogAsync(match.Id, request, 401, cancellationToken).ConfigureAwait(false);
            return Invalid("API key is not active.", match);
        }

        if (match.ExpiresAt <= DateTime.UtcNow)
        {
            await apiKeys.UpdateAsync(ToApiKeyDto(match) with
            {
                Status = ApiKeyStatus.Expired,
                IsActive = false
            }).ConfigureAwait(false);
            await WriteUsageLogAsync(match.Id, request, 401, cancellationToken).ConfigureAwait(false);
            return Invalid("API key has expired.", match);
        }

        await apiKeys.TouchApiKeyLastUsedAsync(match.Id, new TouchApiKeyLastUsedRequestDto()).ConfigureAwait(false);
        await WriteUsageLogAsync(match.Id, request, 200, cancellationToken).ConfigureAwait(false);

        return new ValidateApiKeyResultDto
        {
            IsValid = true,
            ApiKeyId = match.Id,
            PermissionGroupName = match.PermissionGroupName,
            CreatedByUserId = match.CreatedByUserId,
            Name = match.Name
        };
    }

    public async Task<bool> PermissionGroupExistsAsync(
        string permissionGroupName,
        CancellationToken cancellationToken = default)
    {
        var result = await permissionGroups.GetByPkAsync(permissionGroupName).ConfigureAwait(false);
        return result.Code == 0 && result.Value is not null;
    }

    private async Task WriteUsageLogAsync(
        Guid apiKeyId,
        ValidateApiKeyRequestDto request,
        int statusCode,
        CancellationToken cancellationToken)
    {
        var urlPath = string.IsNullOrWhiteSpace(request.UrlPath) ? "/" : request.UrlPath.Trim();
        if (urlPath.Length > 1000)
            urlPath = urlPath[..1000];

        var ip = string.IsNullOrWhiteSpace(request.IpAddress) ? null : request.IpAddress.Trim();
        if (ip is { Length: > 64 })
            ip = ip[..64];

        await usageLogs.InsertAsync(new ApiKeyUsageLogDto
        {
            ApiKeyId = apiKeyId,
            HttpMethod = ParseHttpMethod(request.HttpMethod),
            UrlPath = urlPath,
            StatusCode = statusCode,
            IpAddress = ip,
            CreatedDate = DateTime.UtcNow
        }).ConfigureAwait(false);
    }

    private static HttpMethodType ParseHttpMethod(string? method)
    {
        if (string.IsNullOrWhiteSpace(method))
            return HttpMethodType.Get;

        return Enum.TryParse<HttpMethodType>(method.Trim(), ignoreCase: true, out var parsed)
            ? parsed
            : HttpMethodType.Get;
    }

